"""Stock reservation for a small inventory."""


def reserve(available: int, requested: int) -> int:
    """Return the stock left after reserving ``requested`` units.

    Raises ValueError when the available stock is negative, the request is not
    positive, or the request exceeds the available stock.
    """
    if available < 0:
        raise ValueError("available stock must not be negative")
    if requested <= 0:
        raise ValueError("requested units must be positive")
    if requested > available:
        raise ValueError("requested units exceed available stock")
    return available - requested

import pytest

from inventory.stock import reserve


def test_reserve_reduces_stock() -> None:
    assert reserve(10, 3) == 7


def test_reserve_allows_all_stock() -> None:
    assert reserve(5, 5) == 0


@pytest.mark.parametrize(
    ("available", "requested"), [(-1, 1), (5, 0), (5, -2), (5, 6)]
)
def test_reserve_rejects_invalid_requests(available: int, requested: int) -> None:
    with pytest.raises(ValueError):
        reserve(available, requested)
